//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_2
  : public dummy_plm::ex_port_2<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_2<HLS_L>            this_type;
    typedef dummy_plm::ex_port_2<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_2( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_2") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, WE1_reg( HLS_CAT_NAMES(in_name,"WE1_reg") ),
        CE1_reg( HLS_CAT_NAMES(in_name,"CE1_reg") ),
        D1_reg( HLS_CAT_NAMES(in_name,"D1_reg") ),
        A1_reg( HLS_CAT_NAMES(in_name,"A1_reg") ),
        WEM1_reg( HLS_CAT_NAMES(in_name,"WEM1_reg") )
		, WE1_p( HLS_CAT_NAMES(in_name,"WE1_p") ),
        CE1_p( HLS_CAT_NAMES(in_name,"CE1_p") ),
        D1_p( HLS_CAT_NAMES(in_name,"D1_p") ),
        A1_p( HLS_CAT_NAMES(in_name,"A1_p") ),
        WEM1_p( HLS_CAT_NAMES(in_name,"WEM1_p") )
    {
        this->WE1(WE1_reg);
        this->CE1(CE1_reg);
        this->D1(D1_reg);
        this->A1(A1_reg);
        this->WEM1(WEM1_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        WE1_p(iface.WE1);
        CE1_p(iface.CE1);
        D1_p(iface.D1);
        A1_p(iface.A1);
        WEM1_p(iface.WEM1);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            WE1_p = 0;
            WEM1_p = 0;
            CE1_p = 0;
        } else {
            WE1_p.write( WE1_reg.read() );
            CE1_p.write( CE1_reg.read() );
            WEM1_p.write( WEM1_reg.read() );
            D1_p.write( D1_reg.read() );
            A1_p.write( A1_reg.read() );

        }
    }
  public:

        sc_signal< bool > WE1_reg;
        sc_signal< bool > CE1_reg;
        sc_signal< sc_uint<64> > D1_reg;
        sc_signal< sc_uint<9> > A1_reg;
        sc_signal< sc_uint<64> > WEM1_reg;
        sc_out< bool > WE1_p;
        sc_out< bool > CE1_p;
        sc_out< sc_uint<64> > D1_p;
        sc_out< sc_uint<9> > A1_p;
        sc_out< sc_uint<64> > WEM1_p;
};

#endif

