#if !defined(STRATUS_VLG)
//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_3
  : public dummy_plm::ex_port_3<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_3<HLS_L>            this_type;
    typedef dummy_plm::ex_port_3<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_3( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_3") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, WE2_reg( HLS_CAT_NAMES(in_name,"WE2_reg") ),
        CE2_reg( HLS_CAT_NAMES(in_name,"CE2_reg") ),
        D2_reg( HLS_CAT_NAMES(in_name,"D2_reg") ),
        A2_reg( HLS_CAT_NAMES(in_name,"A2_reg") ),
        WEM2_reg( HLS_CAT_NAMES(in_name,"WEM2_reg") )
		, WE2_p( HLS_CAT_NAMES(in_name,"WE2_p") ),
        CE2_p( HLS_CAT_NAMES(in_name,"CE2_p") ),
        D2_p( HLS_CAT_NAMES(in_name,"D2_p") ),
        A2_p( HLS_CAT_NAMES(in_name,"A2_p") ),
        WEM2_p( HLS_CAT_NAMES(in_name,"WEM2_p") )
    {
        this->WE2(WE2_reg);
        this->CE2(CE2_reg);
        this->D2(D2_reg);
        this->A2(A2_reg);
        this->WEM2(WEM2_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        WE2_p(iface.WE2);
        CE2_p(iface.CE2);
        D2_p(iface.D2);
        A2_p(iface.A2);
        WEM2_p(iface.WEM2);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            WE2_p = 0;
            WEM2_p = 0;
            CE2_p = 0;
        } else {
            WE2_p.write( WE2_reg.read() );
            CE2_p.write( CE2_reg.read() );
            WEM2_p.write( WEM2_reg.read() );
            D2_p.write( D2_reg.read() );
            A2_p.write( A2_reg.read() );

        }
    }
  public:

        sc_signal< bool > WE2_reg;
        sc_signal< bool > CE2_reg;
        sc_signal< sc_uint<64> > D2_reg;
        sc_signal< sc_uint<9> > A2_reg;
        sc_signal< sc_uint<64> > WEM2_reg;
        sc_out< bool > WE2_p;
        sc_out< bool > CE2_p;
        sc_out< sc_uint<64> > D2_p;
        sc_out< sc_uint<9> > A2_p;
        sc_out< sc_uint<64> > WEM2_p;
};

#endif

