template <typename HLS_L>
class dummy_plm::reg_ex_port_6
  : public dummy_plm::ex_port_6<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_6<HLS_L>            this_type;
    typedef dummy_plm::ex_port_6<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_6( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_6") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, WE5_reg( HLS_CAT_NAMES(in_name,"WE5_reg") ),
        CE5_reg( HLS_CAT_NAMES(in_name,"CE5_reg") ),
        D5_reg( HLS_CAT_NAMES(in_name,"D5_reg") ),
        A5_reg( HLS_CAT_NAMES(in_name,"A5_reg") ),
        WEM5_reg( HLS_CAT_NAMES(in_name,"WEM5_reg") )
		, WE5_p( HLS_CAT_NAMES(in_name,"WE5_p") ),
        CE5_p( HLS_CAT_NAMES(in_name,"CE5_p") ),
        D5_p( HLS_CAT_NAMES(in_name,"D5_p") ),
        A5_p( HLS_CAT_NAMES(in_name,"A5_p") ),
        WEM5_p( HLS_CAT_NAMES(in_name,"WEM5_p") )
    {
        this->WE5(WE5_reg);
        this->CE5(CE5_reg);
        this->D5(D5_reg);
        this->A5(A5_reg);
        this->WEM5(WEM5_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        WE5_p(iface.WE5);
        CE5_p(iface.CE5);
        D5_p(iface.D5);
        A5_p(iface.A5);
        WEM5_p(iface.WEM5);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            WE5_p = 0;
            WEM5_p = 0;
            CE5_p = 0;
        } else {
            WE5_p.write( WE5_reg.read() );
            CE5_p.write( CE5_reg.read() );
            WEM5_p.write( WEM5_reg.read() );
            D5_p.write( D5_reg.read() );
            A5_p.write( A5_reg.read() );

        }
    }
  public:

        sc_signal< bool > WE5_reg;
        sc_signal< bool > CE5_reg;
        sc_signal< sc_uint<64> > D5_reg;
        sc_signal< sc_uint<9> > A5_reg;
        sc_signal< sc_uint<64> > WEM5_reg;
        sc_out< bool > WE5_p;
        sc_out< bool > CE5_p;
        sc_out< sc_uint<64> > D5_p;
        sc_out< sc_uint<9> > A5_p;
        sc_out< sc_uint<64> > WEM5_p;
};

