//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_7
  : public dummy_plm::ex_port_7<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_7<HLS_L>            this_type;
    typedef dummy_plm::ex_port_7<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_7( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_7") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, WE6_reg( HLS_CAT_NAMES(in_name,"WE6_reg") ),
        CE6_reg( HLS_CAT_NAMES(in_name,"CE6_reg") ),
        D6_reg( HLS_CAT_NAMES(in_name,"D6_reg") ),
        A6_reg( HLS_CAT_NAMES(in_name,"A6_reg") ),
        WEM6_reg( HLS_CAT_NAMES(in_name,"WEM6_reg") )
		, WE6_p( HLS_CAT_NAMES(in_name,"WE6_p") ),
        CE6_p( HLS_CAT_NAMES(in_name,"CE6_p") ),
        D6_p( HLS_CAT_NAMES(in_name,"D6_p") ),
        A6_p( HLS_CAT_NAMES(in_name,"A6_p") ),
        WEM6_p( HLS_CAT_NAMES(in_name,"WEM6_p") )
    {
        this->WE6(WE6_reg);
        this->CE6(CE6_reg);
        this->D6(D6_reg);
        this->A6(A6_reg);
        this->WEM6(WEM6_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        WE6_p(iface.WE6);
        CE6_p(iface.CE6);
        D6_p(iface.D6);
        A6_p(iface.A6);
        WEM6_p(iface.WEM6);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            WE6_p = 0;
            WEM6_p = 0;
            CE6_p = 0;
        } else {
            WE6_p.write( WE6_reg.read() );
            CE6_p.write( CE6_reg.read() );
            WEM6_p.write( WEM6_reg.read() );
            D6_p.write( D6_reg.read() );
            A6_p.write( A6_reg.read() );

        }
    }
  public:

        sc_signal< bool > WE6_reg;
        sc_signal< bool > CE6_reg;
        sc_signal< sc_uint<64> > D6_reg;
        sc_signal< sc_uint<9> > A6_reg;
        sc_signal< sc_uint<64> > WEM6_reg;
        sc_out< bool > WE6_p;
        sc_out< bool > CE6_p;
        sc_out< sc_uint<64> > D6_p;
        sc_out< sc_uint<9> > A6_p;
        sc_out< sc_uint<64> > WEM6_p;
};

#endif

