#if !defined(STRATUS_VLG)
//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_8
  : public dummy_plm::ex_port_8<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_8<HLS_L>            this_type;
    typedef dummy_plm::ex_port_8<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_8( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_8") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, WE7_reg( HLS_CAT_NAMES(in_name,"WE7_reg") ),
        CE7_reg( HLS_CAT_NAMES(in_name,"CE7_reg") ),
        D7_reg( HLS_CAT_NAMES(in_name,"D7_reg") ),
        A7_reg( HLS_CAT_NAMES(in_name,"A7_reg") ),
        WEM7_reg( HLS_CAT_NAMES(in_name,"WEM7_reg") )
		, WE7_p( HLS_CAT_NAMES(in_name,"WE7_p") ),
        CE7_p( HLS_CAT_NAMES(in_name,"CE7_p") ),
        D7_p( HLS_CAT_NAMES(in_name,"D7_p") ),
        A7_p( HLS_CAT_NAMES(in_name,"A7_p") ),
        WEM7_p( HLS_CAT_NAMES(in_name,"WEM7_p") )
    {
        this->WE7(WE7_reg);
        this->CE7(CE7_reg);
        this->D7(D7_reg);
        this->A7(A7_reg);
        this->WEM7(WEM7_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        WE7_p(iface.WE7);
        CE7_p(iface.CE7);
        D7_p(iface.D7);
        A7_p(iface.A7);
        WEM7_p(iface.WEM7);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            WE7_p = 0;
            WEM7_p = 0;
            CE7_p = 0;
        } else {
            WE7_p.write( WE7_reg.read() );
            CE7_p.write( CE7_reg.read() );
            WEM7_p.write( WEM7_reg.read() );
            D7_p.write( D7_reg.read() );
            A7_p.write( A7_reg.read() );

        }
    }
  public:

        sc_signal< bool > WE7_reg;
        sc_signal< bool > CE7_reg;
        sc_signal< sc_uint<64> > D7_reg;
        sc_signal< sc_uint<9> > A7_reg;
        sc_signal< sc_uint<64> > WEM7_reg;
        sc_out< bool > WE7_p;
        sc_out< bool > CE7_p;
        sc_out< sc_uint<64> > D7_p;
        sc_out< sc_uint<9> > A7_p;
        sc_out< sc_uint<64> > WEM7_p;
};

#endif

