class dummy_plm::port_11<HLS_L,HLS_ACCESS,HLS_MAPPING>::shared_5 :
    public sc_module,
	public cynw_clk_rst_facade
{   
  public:
    typedef dummy_plm::port_11<HLS_L,HLS_ACCESS,HLS_MAPPING>           port_type;

    typedef typename port_type::shared_5                  this_type;
   typedef sc_uint<9>                  address_type;
   typedef sc_uint<64>                data_type;
  public:
    SC_HAS_PROCESS(shared_5);
    shared_5( sc_module_name in_name=sc_module_name( sc_gen_unique_name("shared_5") ), unsigned options_in=0)
      : sc_module(in_name)
      , m_port(in_name)
      , m_options(options_in)
    {


        SC_METHOD(mux_inputs);
        sensitive << if1.CE10;
        sensitive << if1.A10;
        sensitive << if2.CE10;
        sensitive << if2.A10;
        sensitive << if3.CE10;
        sensitive << if3.A10;
        sensitive << if4.CE10;
        sensitive << if4.A10;
        sensitive << if5.CE10;
        sensitive << if5.A10;

        SC_METHOD(gen_out_1);
        sensitive << m_port.Q10;

        SC_METHOD(gen_out_2);
        sensitive << m_port.Q10;

        SC_METHOD(gen_out_3);
        sensitive << m_port.Q10;

        SC_METHOD(gen_out_4);
        sensitive << m_port.Q10;

        SC_METHOD(gen_out_5);
        sensitive << m_port.Q10;
    }

  public:

    //
    // Interface signals.
    //
    dummy_plm_ext_signals_11    if1;
    dummy_plm_ext_signals_11    if2;
    dummy_plm_ext_signals_11    if3;
    dummy_plm_ext_signals_11    if4;
    dummy_plm_ext_signals_11    if5;


    unsigned m_options;

    // 
    // MUX for inputs based on which input is active.
    // Precedence is given to the first port.
    // If neither port is active, the memory inputs are 
    // written to an inactive state.
    //
    void mux_inputs()
    {
        HLS_REMOVE_CONTROL(ON,"");
       if ( (m_options & (HLS::HLS_USING_REG_PORT | HLS::HLS_USING_REG_EX_PORT)) == 0 ) {
            HLS_SET_OUTPUT_DELAY( m_port.CE10, 0.06 );
            HLS_SET_OUTPUT_DELAY( m_port.A10, 0.06 );
       }
        if (if1.CE10.read() == 1) {
            m_port.CE10 = if1.CE10;
            m_port.A10 = if1.A10;
        } else if (if2.CE10.read() == 1) {
            m_port.CE10 = if2.CE10;
            m_port.A10 = if2.A10;
        } else if (if3.CE10.read() == 1) {
            m_port.CE10 = if3.CE10;
            m_port.A10 = if3.A10;
        } else if (if4.CE10.read() == 1) {
            m_port.CE10 = if4.CE10;
            m_port.A10 = if4.A10;
        } else if (if5.CE10.read() == 1) {
            m_port.CE10 = if5.CE10;
            m_port.A10 = if5.A10;
        } else {
            m_port.CE10 = 0;
            m_port.A10 = 0;

        }
    }


    //
    // Method to transfer memory output to if1
    //
    void gen_out_1()
    {
        if1.Q10 = m_port.Q10; 
    }
    


    //
    // Method to transfer memory output to if2
    //
    void gen_out_2()
    {
        if2.Q10 = m_port.Q10; 
    }
    


    //
    // Method to transfer memory output to if3
    //
    void gen_out_3()
    {
        if3.Q10 = m_port.Q10; 
    }
    


    //
    // Method to transfer memory output to if4
    //
    void gen_out_4()
    {
        if4.Q10 = m_port.Q10; 
    }
    


    //
    // Method to transfer memory output to if5
    //
    void gen_out_5()
    {
        if5.Q10 = m_port.Q10; 
    }
    


    template <class W>
    void bind( W& iface )
    {
        m_port.CE10(iface.CE10);
        m_port.Q10(iface.Q10);
        m_port.A10(iface.A10);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

	port_type m_port;
};
#endif


