//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_12
  : public dummy_plm::ex_port_12<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_12<HLS_L>            this_type;
    typedef dummy_plm::ex_port_12<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_12( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_12") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, CE11_reg( HLS_CAT_NAMES(in_name,"CE11_reg") ),
        Q11_reg( HLS_CAT_NAMES(in_name,"Q11_reg") ),
        A11_reg( HLS_CAT_NAMES(in_name,"A11_reg") )
		, CE11_p( HLS_CAT_NAMES(in_name,"CE11_p") ),
        Q11_p( HLS_CAT_NAMES(in_name,"Q11_p") ),
        A11_p( HLS_CAT_NAMES(in_name,"A11_p") )
    {
        this->CE11(CE11_reg);
        this->Q11(Q11_reg);
        this->A11(A11_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        CE11_p(iface.CE11);
        Q11_p(iface.Q11);
        A11_p(iface.A11);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            CE11_p = 0;
        } else {
            CE11_p.write( CE11_reg.read() );
            Q11_reg.write( Q11_p.read() );
            A11_p.write( A11_reg.read() );

        }
    }
  public:

        sc_signal< bool > CE11_reg;
        sc_signal< sc_uint<64> > Q11_reg;
        sc_signal< sc_uint<9> > A11_reg;
        sc_out< bool > CE11_p;
        sc_out< sc_uint<9> > A11_p;
        sc_in< sc_uint<64> > Q11_p;
};

#endif

