//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_14
  : public dummy_plm::ex_port_14<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_14<HLS_L>            this_type;
    typedef dummy_plm::ex_port_14<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_14( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_14") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, CE13_reg( HLS_CAT_NAMES(in_name,"CE13_reg") ),
        Q13_reg( HLS_CAT_NAMES(in_name,"Q13_reg") ),
        A13_reg( HLS_CAT_NAMES(in_name,"A13_reg") )
		, CE13_p( HLS_CAT_NAMES(in_name,"CE13_p") ),
        Q13_p( HLS_CAT_NAMES(in_name,"Q13_p") ),
        A13_p( HLS_CAT_NAMES(in_name,"A13_p") )
    {
        this->CE13(CE13_reg);
        this->Q13(Q13_reg);
        this->A13(A13_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        CE13_p(iface.CE13);
        Q13_p(iface.Q13);
        A13_p(iface.A13);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            CE13_p = 0;
        } else {
            CE13_p.write( CE13_reg.read() );
            Q13_reg.write( Q13_p.read() );
            A13_p.write( A13_reg.read() );

        }
    }
  public:

        sc_signal< bool > CE13_reg;
        sc_signal< sc_uint<64> > Q13_reg;
        sc_signal< sc_uint<9> > A13_reg;
        sc_out< bool > CE13_p;
        sc_out< sc_uint<9> > A13_p;
        sc_in< sc_uint<64> > Q13_p;
};

#endif

