template <typename HLS_L,typename HLS_ACCESS,HLS::HLS_INDEX_MAPPING_OPTIONS HLS_MAPPING>
class dummy_plm::port_14<HLS_L,HLS_ACCESS,HLS_MAPPING>::shared_2 :
    public sc_module,
	public cynw_clk_rst_facade
{   
  public:
    typedef dummy_plm::port_14<HLS_L,HLS_ACCESS,HLS_MAPPING>           port_type;

    typedef typename port_type::shared_2                  this_type;
   typedef sc_uint<9>                  address_type;
   typedef sc_uint<64>                data_type;
  public:
    SC_HAS_PROCESS(shared_2);
    shared_2( sc_module_name in_name=sc_module_name( sc_gen_unique_name("shared_2") ), unsigned options_in=0)
      : sc_module(in_name)
      , m_port(in_name)
      , m_options(options_in)
    {


        SC_METHOD(mux_inputs);
        sensitive << if1.CE13;
        sensitive << if1.A13;
        sensitive << if2.CE13;
        sensitive << if2.A13;

        SC_METHOD(gen_out_1);
        sensitive << m_port.Q13;

        SC_METHOD(gen_out_2);
        sensitive << m_port.Q13;
    }

  public:

    //
    // Interface signals.
    //
    dummy_plm_ext_signals_14    if1;
    dummy_plm_ext_signals_14    if2;


    unsigned m_options;

    // 
    // MUX for inputs based on which input is active.
    // Precedence is given to the first port.
    // If neither port is active, the memory inputs are 
    // written to an inactive state.
    //
    void mux_inputs()
    {
        HLS_REMOVE_CONTROL(ON,"");
       if ( (m_options & (HLS::HLS_USING_REG_PORT | HLS::HLS_USING_REG_EX_PORT)) == 0 ) {
            HLS_SET_OUTPUT_DELAY( m_port.CE13, 0.06 );
            HLS_SET_OUTPUT_DELAY( m_port.A13, 0.06 );
       }
        if (if1.CE13.read() == 1) {
            m_port.CE13 = if1.CE13;
            m_port.A13 = if1.A13;
        } else if (if2.CE13.read() == 1) {
            m_port.CE13 = if2.CE13;
            m_port.A13 = if2.A13;
        } else {
            m_port.CE13 = 0;
            m_port.A13 = 0;

        }
    }


    //
    // Method to transfer memory output to if1
    //
    void gen_out_1()
    {
        if1.Q13 = m_port.Q13; 
    }
    


    //
    // Method to transfer memory output to if2
    //
    void gen_out_2()
    {
        if2.Q13 = m_port.Q13; 
    }
    


    template <class W>
    void bind( W& iface )
    {
        m_port.CE13(iface.CE13);
        m_port.Q13(iface.Q13);
        m_port.A13(iface.A13);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

	port_type m_port;
};
#endif


