//
// PIN-level export metaport with a register included.
//
// Select this version by either omitting the HLS_L template argument,
// or by setting it to PIN.
//
template <typename HLS_L>
class dummy_plm::reg_ex_port_16
  : public dummy_plm::ex_port_16<HLS_L>,
	public sc_module,
	public cynw_clk_rst

{
  public:
    typedef dummy_plm::reg_ex_port_16<HLS_L>            this_type;
    typedef dummy_plm::ex_port_16<HLS_L>            base_type;
   typedef sc_uint<9>                       address_type;
   typedef sc_uint<64>                      data_type;

    SC_HAS_PROCESS(this_type);

    reg_ex_port_16( sc_module_name in_name=sc_module_name( sc_gen_unique_name("reg_ex_port_16") ) )
        : base_type(in_name)
		, sc_module(in_name)
		, CE15_reg( HLS_CAT_NAMES(in_name,"CE15_reg") ),
        Q15_reg( HLS_CAT_NAMES(in_name,"Q15_reg") ),
        A15_reg( HLS_CAT_NAMES(in_name,"A15_reg") )
		, CE15_p( HLS_CAT_NAMES(in_name,"CE15_p") ),
        Q15_p( HLS_CAT_NAMES(in_name,"Q15_p") ),
        A15_p( HLS_CAT_NAMES(in_name,"A15_p") )
    {
        this->CE15(CE15_reg);
        this->Q15(Q15_reg);
        this->A15(A15_reg);


        SC_METHOD(do_reg);
        sensitive << clk.pos();
        dont_initialize();

	}

  public:


    template <class W>
    void bind( W& iface )
    {
        CE15_p(iface.CE15);
        Q15_p(iface.Q15);
        A15_p(iface.A15);

    }

    template <class W>
    void operator()( W& iface )
    {
      bind(iface);
    }

    void do_reg()
    {
        if ( rst_active() ) 
        {
	         HLS_SET_IS_RESET_BLOCK("do_reg");
            CE15_p = 0;
        } else {
            CE15_p.write( CE15_reg.read() );
            Q15_reg.write( Q15_p.read() );
            A15_p.write( A15_reg.read() );

        }
    }
  public:

        sc_signal< bool > CE15_reg;
        sc_signal< sc_uint<64> > Q15_reg;
        sc_signal< sc_uint<9> > A15_reg;
        sc_out< bool > CE15_p;
        sc_out< sc_uint<9> > A15_p;
        sc_in< sc_uint<64> > Q15_p;
};

#endif

