    typedef cynw_memory_ref< this_type, HLS_ACCESS,HLS_MAPPING > ref_type;
    typedef dummy_plm::types<CYN::TLM>     types;
    typedef sc_port< cynw_memory_if< sc_uint<9>, sc_uint<64> > > base_type;
    typedef sc_uint<9>                       address_type;
